// Zwraca przetłumaczony tekst dla danego klucza w aktualnym języku (z awaryjnym powrotem do polskiego).
function t(klucz) {
    const jezyk = window.aktualnyJezyk || 'pl';
    return (TLUMACZENIA[jezyk] && TLUMACZENIA[jezyk][klucz]) || (TLUMACZENIA.pl && TLUMACZENIA.pl[klucz]) || klucz;
}

// Ustawia język: podmienia tekst wszystkich elementów oznaczonych data-i18n / data-i18n-placeholder,
// zapamiętuje wybór w localStorage (przetrwa odświeżenie strony i kolejne wizyty).
function ustawJezyk(kod) {
    if (!TLUMACZENIA[kod]) kod = 'pl';
    window.aktualnyJezyk = kod;
    localStorage.setItem('jezyk_priceai', kod);
    document.documentElement.lang = kod;

    document.querySelectorAll('[data-i18n]').forEach(el => {
        el.textContent = t(el.getAttribute('data-i18n'));
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
        el.innerHTML = t(el.getAttribute('data-i18n-html'));
    });
    document.querySelectorAll('[data-i18n-ph]').forEach(el => {
        el.placeholder = t(el.getAttribute('data-i18n-ph'));
    });
    document.querySelectorAll('[data-i18n-tip]').forEach(el => {
        el.setAttribute('data-tip', t(el.getAttribute('data-i18n-tip')));
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        el.title = t(el.getAttribute('data-i18n-title'));
    });

    if (typeof renderujTabele === 'function' && typeof globalnyKatalog !== 'undefined') renderujTabele(globalnyKatalog);
    if (typeof pobierzZamowienia === 'function' && document.getElementById('tabela-zamowienia')) pobierzZamowienia();
    if (typeof pobierzMagazyn === 'function' && document.getElementById('tabela-magazyn')) pobierzMagazyn();
}

function inicjujJezyk() {
    const zapisany = localStorage.getItem('jezyk_priceai') || 'pl';
    const select = document.getElementById('langSelect');
    if (select) select.value = zapisany;
    ustawJezyk(zapisany);
}

document.addEventListener('DOMContentLoaded', inicjujJezyk);